sys_script_include.script:
/**
 * JevClient — fluent HTTP wrapper around the TypeSafe /v1/systemone endpoint.
 *
 * Uses ServiceNow RESTMessageV2 (no npm, works in the SN sandbox).
 * API key and endpoint read from sys_properties — never hard-coded.
 *
 * Usage:
 *   var result = new x_146833_jevnowint.JevClient()
 *       .withState('Help! Payouts failing for 3 days.')
 *       .ask('is_urgent',  x_146833_jevnowint.JevQuestions.noul('Does this convey urgency?'))
 *       .ask('department', x_146833_jevnowint.JevQuestions.choice('Which team?', {
 *           billing:   'Payments, invoicing, refunds',
 *           technical: 'Bugs, outages, integrations',
 *           sales:     'Pricing, upgrades, new accounts'
 *       }))
 *       .ask('severity',   x_146833_jevnowint.JevQuestions.score('How severe?', [
 *           'Minimal', 'Low', 'Medium', 'High'
 *       ]))
 *       .evaluate();
 *
 *   if (result.success) {
 *       gs.info(result.answers.is_urgent.noul);      // 0.0 – 1.0
 *       gs.info(result.answers.department.choice);   // "billing"
 *       gs.info(result.answers.severity.score);      // 0.0 – 3.0
 *   }
 */
var JevClient = Class.create();

JevClient.prototype = {

    initialize: function() {
        this._state     = null;
        this._questions = {};
        this._apiUrl    = gs.getProperty('x_146833_jevnowint.api_url',
                              'https://api.typesafe.ai/v1/systemone');
        this._model     = gs.getProperty('x_146833_jevnowint.model', 'jev-latest');
        this._apiKey    = gs.getProperty('x_146833_jevnowint.api_key', '');
    },

    // ── Fluent builder ────────────────────────────────────────────────────────

    /**
     * Set the state (context) to evaluate.
     * @param {string|object} state
     * @returns {JevClient}
     */
    withState: function(state) {
        this._state = (typeof state === 'object') ? JSON.stringify(state) : state;
        return this;
    },

    /**
     * Add a typed question. Chain multiple .ask() calls for parallel evaluation.
     * @param {string} id       - Key used in the answers map
     * @param {object} question - Built by JevQuestions.noul/choice/score
     * @returns {JevClient}
     */
    ask: function(id, question) {
        this._questions[id] = question;
        return this;
    },

    // ── Execute ───────────────────────────────────────────────────────────────

    /**
     * Send all questions to Jev in a single API call.
     * @returns {{ success: boolean, answers: object, model: string, usage: object, error: string }}
     */
    evaluate: function() {
        if (!this._apiKey) {
            gs.error('JevClient: x_146833_jevnowint.api_key sys_property is not set.');
            return { success: false, error: 'API key not configured.' };
        }
        if (this._state === null) {
            gs.error('JevClient: call withState() before evaluate().');
            return { success: false, error: 'No state provided.' };
        }
        if (Object.keys(this._questions).length === 0) {
            gs.error('JevClient: call ask() with at least one question before evaluate().');
            return { success: false, error: 'No questions provided.' };
        }

        var payload = JSON.stringify({
            state:     this._state,
            model:     this._model,
            questions: this._questions
        });

        try {
            var rm = new sn_ws.RESTMessageV2();
            rm.setEndpoint(this._apiUrl);
            rm.setHttpMethod('POST');
            rm.setRequestHeader('Authorization', 'Bearer ' + this._apiKey);
            rm.setRequestHeader('Content-Type',  'application/json');
            rm.setRequestBody(payload);

            var response   = rm.execute();
            var statusCode = response.getStatusCode();
            var body       = response.getBody();

            if (statusCode !== 200) {
                gs.error('JevClient: HTTP ' + statusCode + ' — ' + body);
                return { success: false, error: 'HTTP ' + statusCode + ': ' + body };
            }

            var parsed = JSON.parse(body);
            return {
                success: true,
                answers: parsed.answers,
                model:   parsed.model,
                usage:   parsed.usage
            };

        } catch (e) {
            gs.error('JevClient: exception — ' + e.message);
            return { success: false, error: e.message };
        }
    },

    type: 'JevClient'
};
